// # SIGKILL cannot be caught; 0 and NSIG are out of range
// def errors() -> None:
//     try:
//         signal.signal(signal.SIGKILL, count)  # tpyc: ok -- OSError(EINVAL)
//     except OSError as e:
//         print("errors: SIGKILL", e.errno, e)
//     for sig in [0, -1, 1000]:
//         try:
//             signal.signal(sig, count)
//         except ValueError as e:
//             print("errors:", sig, e)
//     try:
//         types.FrameType()  # tpyc: ok -- no frame objects, as in CPython
//     except TypeError as e:
//         print("errors: FrameType", e)
void errors() {
    {
        try {
            ::tpystd::signal::signal(::tpy_const_sigkill, count);
        } catch (const ::tpy::OSError& e) {
            std::cout << "errors: SIGKILL" << " " << e.error_number << " " << e << "\n" << ::tpy::check_signals;
        }
    }
    auto __obj_0 = {0, -1, 1000};
    auto __beg_0 = __obj_0.begin();
    auto __end_0 = __obj_0.end();
    for (; __beg_0 != __end_0; ++__beg_0) {
        int32_t sig = *__beg_0;
        {
            try {
                ::tpystd::signal::signal(sig, count);
            } catch (const ::tpy::ValueError& e) {
                std::cout << "errors:" << " " << sig << " " << e << "\n" << ::tpy::check_signals;
            }
        }
    }
    {
        try {
            (void)(::tpystd::types::FrameType());
        } catch (const ::tpy::TypeError& e) {
            std::cout << "errors: FrameType" << " " << e << "\n" << ::tpy::check_signals;
        }
    }
}

